// ---------- Annahmen ----------
h_assume: "Annahmen & Regelwerke",
as_1: "Ladeeinheit: Artikel werden lagenweise auf das gewählte Ladehilfsmittel gepackt (Drehung in der Ebene erlaubt), begrenzt durch Ladehöhe und Maximalgewicht.",
as_2: "Kleinteile (≤ 600 mm, ≤ 15 kg, ≤ 30 l, geringe Menge) gehen ins Fachbodenregal (Fach 950 × 480 × 380 mm, 6 Ebenen, max. 100 kg/Fach). Langgut über 2,5 m ins Kragarmregal.",
as_3: "Palettenregal: Feldteilung für 3 Europaletten (Traverse 2,7 m) bzw. 2 Industriepaletten, Freimaß 250 mm je Ebene, 1 m Abstand unter Decke/Sprinkler. Gangbreiten (Richtwerte): Frontstapler 3,8 m, Schubmast 2,9 m, Schmalgang 1,8 m, RBG 1,6 m, Kragarm 2,4 m, Fachboden 1,2 m.",
as_4: "Automatische Technikwahl Normalware: ab 2.500 Palettenplätzen Hochregallager (wenn zugelassen), ab 1.200 Plätzen und ≥ 9 m Halle Schmalgang, sonst Schubmast. Tiefkühl/Kühl ab 150 Plätzen Verschieberegal (spart Gangfläche und Kälteenergie).",
as_5: "Gefahrstoffe je Lagerklasse in eigenem Lagerabschnitt eines separaten Gebäudes (vorsichtige Annahme). Zusammenlagerung im Einzelfall nach TRGS 510 Anlage 4 prüfen.",
as_6: "Leistung (Spiele je Stunde): Frontstapler 20, Schubmast 18, Schmalgang 22, RBG 35, Mehrwegestapler 12, Horizontaltransport 25, Kommissionierung 80 Pos./h, 6,5 produktive Stunden je Schicht. 33 Paletten je LKW, 1 LKW je Tor und Stunde, Spitzenfaktor 1,5.",
as_7: "Regelwerke (Deutschland): DIN EN 15512 / 15620 / 15635 (Regale), DGUV Regel 108-007 (Lagereinrichtungen), DGUV Vorschrift 68 (Flurförderzeuge), ASR A1.8 (Verkehrswege), ASR A2.2 (Brandschutz), ASR A2.3 (Fluchtwege), ASR A3.4 (Beleuchtung), ASR A4.1/A4.2 (Sanitär/Pausenräume), TRGS 510 (Gefahrstofflagerung), AwSV (Auffangräume), MIndBauRL (Industriebau).",
disclaimer: "Richtwerte für die Vorplanung. Ersetzt keine Fachplanung, kein Brandschutzkonzept und keine Gefährdungsbeurteilung. Angaben ohne Gewähr.",

// ---------- Rechtliches ----------
foot_privacy: "Datenschutz",
foot_imprint: "Impressum",
legal_note: "",
dp_h: "Datenschutzerklärung",
dp_stand: "Stand: Oktober 2026",
dp_1h: "1. Verantwortlicher",
dp_2h: "2. Das Wichtigste in Kürze",
dp_2p: "Der Lagerplaner ist ein reines Rechenwerkzeug, das vollständig in Ihrem Browser läuft. Ihre Eingaben (Artikel, Maße, Gewichte, Mengen und Einstellungen) werden <strong>nicht an uns oder an Dritte übertragen und nicht gespeichert</strong>. Nach dem Neuladen der Seite sind sie verschwunden. Es gibt keine Registrierung, keine Cookies, kein Tracking, keine Analyse-Werkzeuge und keine Werbung.",
dp_3h: "3. Hosting und Server-Logfiles",
dp_3p: "Diese Website wird bei der Cloudflare, Inc., 101 Townsend St., San Francisco, CA 94107, USA (Cloudflare Pages) gehostet. Beim Aufruf verarbeitet Cloudflare technisch notwendige Verbindungsdaten, insbesondere IP-Adresse, Datum und Uhrzeit, aufgerufene Datei, Browsertyp und Betriebssystem. Dies ist erforderlich, um die Seite auszuliefern und vor Angriffen zu schützen. Rechtsgrundlage ist Art. 6 Abs. 1 lit. f DSGVO (berechtigtes Interesse an einem sicheren und funktionsfähigen Betrieb). Eine Verarbeitung in den USA ist möglich; Cloudflare ist unter dem EU-US Data Privacy Framework zertifiziert, ergänzend gelten Standardvertragsklauseln. Weitere Informationen: <a href=\"https://www.cloudflare.com/privacypolicy/\" target=\"_blank\" rel=\"noopener\">cloudflare.com/privacypolicy</a>.",
dp_4h: "4. Keine Inhalte von Drittanbietern",
dp_4p: "Schriftarten (Barlow, Barlow Condensed, JetBrains Mono, Vazirmatn) und die 3D-Bibliothek three.js werden direkt von diesem Webserver geladen. Es besteht keine Verbindung zu Google Fonts, Content-Delivery-Netzwerken oder sonstigen Servern Dritter.",
dp_5h: "5. Speicherung in Ihrem Browser",
dp_5p: "Wir verwenden keine Cookies. Im Local Storage Ihres Browsers wird ausschließlich die von Ihnen gewählte Sprache gespeichert, damit sie beim nächsten Besuch erhalten bleibt. Diese Speicherung ist für die von Ihnen gewünschte Funktion unbedingt erforderlich (§ 25 Abs. 2 Nr. 2 TDDDG). Sie können sie jederzeit über die Einstellungen Ihres Browsers löschen.",
dp_6h: "6. Kontakt per E-Mail oder Telefon",
dp_6p: "Wenn Sie uns kontaktieren, verarbeiten wir Ihre Angaben (z. B. Name, E-Mail-Adresse, Inhalt der Nachricht) ausschließlich zur Bearbeitung Ihrer Anfrage. Rechtsgrundlage ist Art. 6 Abs. 1 lit. b DSGVO (vorvertragliche Anfrage) bzw. lit. f DSGVO (berechtigtes Interesse an der Beantwortung). Wir löschen die Daten, sobald die Anfrage abschließend bearbeitet ist und keine gesetzlichen Aufbewahrungspflichten bestehen.",
dp_7h: "7. Ihre Rechte",
dp_7p: "Sie haben das Recht auf Auskunft (Art. 15 DSGVO), Berichtigung (Art. 16), Löschung (Art. 17), Einschränkung der Verarbeitung (Art. 18) und Datenübertragbarkeit (Art. 20). Soweit eine Verarbeitung auf Art. 6 Abs. 1 lit. f DSGVO beruht, können Sie ihr jederzeit widersprechen (Art. 21 DSGVO). Eine formlose Nachricht an die oben genannte E-Mail-Adresse genügt. Außerdem können Sie sich bei einer Datenschutz-Aufsichtsbehörde beschweren, zum Beispiel beim Landesbeauftragten für den Datenschutz und die Informationsfreiheit Baden-Württemberg, Lautenschlagerstraße 20, 70173 Stuttgart, <a href=\"https://www.baden-wuerttemberg.datenschutz.de\" target=\"_blank\" rel=\"noopener\">baden-wuerttemberg.datenschutz.de</a>.",
dp_8h: "8. Änderungen",
dp_8p: "Wir passen diese Datenschutzerklärung an, sobald sich die Funktionen der Website ändern. Es gilt die jeweils hier veröffentlichte Fassung.",
im_h: "Impressum",
