im_liab: "Haftungshinweis",
im_liab_p: "Der Lagerplaner liefert unverbindliche Richtwerte für die Vorplanung. Alle Ergebnisse sind ohne Gewähr und ersetzen keine Fachplanung, keine Statik, kein Brandschutzkonzept und keine Gefährdungsbeurteilung. Für Inhalte externer Links sind ausschließlich deren Betreiber verantwortlich.",
