im_copy_p: "Texte, Gestaltung und Programmcode dieses Werkzeugs unterliegen dem deutschen Urheberrecht. Jede Verwertung außerhalb der Grenzen des Urheberrechts bedarf der schriftlichen Zustimmung des Anbieters. Die verwendeten Schriftarten stehen unter der SIL Open Font License, three.js unter der MIT-Lizenz.",
