h_assume: "Assumptions & regulations",
as_1: "Load unit: items are stacked in layers on the selected load carrier (rotation in the horizontal plane allowed), limited by load height and maximum weight.",
as_2: "Small parts (≤ 600 mm, ≤ 15 kg, ≤ 30 l, low quantity) go to shelving (bin 950 × 480 × 380 mm, 6 levels, max. 100 kg/bin). Long goods over 2.5 m go to cantilever racking.",
as_3: "Pallet racking: bay layout for 3 Euro pallets (beam 2.7 m) or 2 industrial pallets, 250 mm clearance per level, 1 m distance below ceiling/sprinklers. Aisle widths (guide values): counterbalance forklift 3.8 m, reach truck 2.9 m, VNA 1.8 m, S/R 1.6 m, cantilever 2.4 m, shelving 1.2 m.",
as_4: "Automatic technology selection for ambient goods: from 2,500 pallet locations AS/RS high-bay (if allowed), from 1,200 locations and ≥ 9 m hall VNA, otherwise reach truck. Frozen/chilled from 150 locations mobile racking (saves aisle space and cooling energy).",
as_5: "Hazardous goods stored per storage class in a dedicated section of a separate building (conservative assumption). Check mixed storage case by case according to TRGS 510 Annex 4.",
as_6: "Performance (cycles per hour): counterbalance forklift 20, reach truck 18, VNA 22, S/R 35, multi-directional forklift 12, horizontal transport 25, picking 80 lines/h, 6.5 productive hours per shift. 33 pallets per truck, 1 truck per door and hour, peak factor 1.5.",
as_7: "Regulations (Germany): DIN EN 15512 / 15620 / 15635 (racking), DGUV Regel 108-007 (storage equipment), DGUV Vorschrift 68 (industrial trucks), ASR A1.8 (traffic routes), ASR A2.2 (fire protection), ASR A2.3 (escape routes), ASR A3.4 (lighting), ASR A4.1/A4.2 (sanitary/break rooms), TRGS 510 (storage of hazardous substances), AwSV (retention areas), MIndBauRL (industrial buildings).",
disclaimer: "Guide values for preliminary planning. Does not replace professional planning, a fire safety concept or a risk assessment. No liability assumed.",

// ---------- Legal ----------
foot_privacy: "Privacy",
foot_imprint: "Legal notice",
legal_note: "This translation is provided for information only; the German version is legally binding.",
dp_h: "Privacy policy",
dp_stand: "Last updated: October 2026",
dp_1h: "1. Controller",
dp_2h: "2. Key points at a glance",
dp_2p: "The warehouse planner is a pure calculation tool that runs entirely in your browser. Your inputs (items, dimensions, weights, quantities and settings) are <strong>not transmitted to us or to third parties and are not stored</strong>. They are gone once you reload the page. There is no registration, no cookies, no tracking, no analytics tools and no advertising.",
dp_3h: "3. Hosting and server log files",
dp_3p: "This website is hosted by Cloudflare, Inc., 101 Townsend St., San Francisco, CA 94107, USA (Cloudflare Pages). When you access it, Cloudflare processes technically necessary connection data, in particular IP address, date and time, requested file, browser type and operating system. This is required to deliver the page and protect it against attacks. The legal basis is Art. 6(1)(f) GDPR (DSGVO) (legitimate interest in secure and functional operation). Processing in the USA is possible; Cloudflare is certified under the EU-US Data Privacy Framework, and standard contractual clauses apply additionally. Further information: <a href=\"https://www.cloudflare.com/privacypolicy/\" target=\"_blank\" rel=\"noopener\">cloudflare.com/privacypolicy</a>.",
dp_4h: "4. No third-party content",
dp_4p: "Fonts (Barlow, Barlow Condensed, JetBrains Mono, Vazirmatn) and the 3D library three.js are loaded directly from this web server. There is no connection to Google Fonts, content delivery networks or any other third-party servers.",
dp_5h: "5. Storage in your browser",
dp_5p: "We do not use cookies. Only the language you selected is stored in your browser's local storage so that it is retained on your next visit. This storage is strictly necessary for the function you requested (§ 25 Abs. 2 Nr. 2 TDDDG). You can delete it at any time via your browser settings.",
dp_6h: "6. Contact by email or phone",
dp_6p: "If you contact us, we process your details (e.g. name, email address, content of the message) solely to handle your enquiry. The legal basis is Art. 6(1)(b) GDPR (DSGVO) (pre-contractual enquiry) or Art. 6(1)(f) GDPR (legitimate interest in responding). We delete the data once the enquiry has been fully dealt with and no statutory retention obligations apply.",
dp_7h: "7. Your rights",
dp_7p: "You have the right of access (Art. 15 GDPR (DSGVO)), rectification (Art. 16), erasure (Art. 17), restriction of processing (Art. 18) and data portability (Art. 20). Where processing is based on Art. 6(1)(f) GDPR, you may object to it at any time (Art. 21 GDPR). An informal message to the email address given above is sufficient. You can also lodge a complaint with a data protection supervisory authority, for example the State Commissioner for Data Protection and Freedom of Information Baden-Württemberg (Landesbeauftragter für den Datenschutz und die Informationsfreiheit Baden-Württemberg), Lautenschlagerstraße 20, 70173 Stuttgart, <a href=\"https://www.baden-wuerttemberg.datenschutz.de\" target=\"_blank\" rel=\"noopener\">baden-wuerttemberg.datenschutz.de</a>.",
dp_8h: "8. Changes",
dp_8p: "We update this privacy policy whenever the website's functions change. The version published here at any given time applies.",
im_h: "Legal notice (Impressum)",
im_sub: "Information pursuant to § 5 DDG",
im_provider: "Provider",
im_brand: "Operating under the brand KeyOne",
im_country: "Germany",
im_contact: "Contact",
im_phone: "Phone",
