// ---------- Annahmen ----------
h_assume: "الافتراضات واللوائح",
as_1: "وحدة التحميل: تُرصّ الأصناف طبقة فوق طبقة على وسيلة التحميل المختارة (يُسمح بالتدوير في المستوى الأفقي)، ضمن حدود ارتفاع الحمولة والوزن الأقصى.",
as_2: "القطع الصغيرة (≤ 600 mm، ≤ 15 kg، ≤ 30 لتر، كمية قليلة) توضع في رفوف الأرفف (رف 950 × 480 × 380 mm، 6 مستويات، بحد أقصى 100 kg لكل رف). البضائع الطويلة التي تزيد عن 2.5 m توضع في الرفوف الكابولية.",
as_3: "رفوف المنصات: تقسيم الخانة لـ 3 منصات أوروبية (عارضة 2.7 m) أو 2 منصة صناعية، خلوص 250 mm لكل مستوى، مسافة 1 m أسفل السقف/الرشاشات. عرض الممرات (قيم استرشادية): رافعة أمامية 3.8 m، ريتش تراك 2.9 m، ممر ضيق 1.8 m، رافعة تخزين 1.6 m، كابولية 2.4 m، رفوف أرفف 1.2 m.",
as_4: "الاختيار التلقائي للتقنية للبضائع العادية: اعتبارًا من 2,500 موقع منصة مستودع عالي الرفوف (إذا كان مسموحًا)، واعتبارًا من 1,200 موقع وارتفاع قاعة ≥ 9 m ممر ضيق، وإلا ريتش تراك. للبضائع المجمدة/المبردة اعتبارًا من 150 موقعًا رفوف متحركة (توفر مساحة الممرات وطاقة التبريد).",
as_5: "تُخزّن المواد الخطرة حسب فئة التخزين في قسم تخزين مستقل داخل مبنى منفصل (افتراض متحفظ). يجب فحص التخزين المشترك في كل حالة على حدة وفق TRGS 510 الملحق 4.",
as_6: "الأداء (دورات في الساعة): رافعة أمامية 20، ريتش تراك 18، ممر ضيق 22، رافعة تخزين 35، رافعة متعددة الاتجاهات 12، نقل أفقي 25، تجهيز الطلبات 80 بندًا/ساعة، 6.5 ساعات إنتاجية لكل وردية. 33 منصة لكل شاحنة، 1 شاحنة لكل بوابة في الساعة، معامل الذروة 1.5.",
as_7: "اللوائح (ألمانيا): DIN EN 15512 / 15620 / 15635 (الرفوف)، DGUV Regel 108-007 (تجهيزات التخزين)، DGUV Vorschrift 68 (معدات المناولة)، ASR A1.8 (ممرات الحركة)، ASR A2.2 (الحماية من الحريق)، ASR A2.3 (مسارات الهروب)، ASR A3.4 (الإضاءة)، ASR A4.1/A4.2 (المرافق الصحية/غرف الاستراحة)، TRGS 510 (تخزين المواد الخطرة)، AwSV (غرف التجميع)، MIndBauRL (المباني الصناعية).",
disclaimer: "قيم استرشادية للتخطيط الأولي. لا تغني عن التخطيط المتخصص ولا عن مفهوم الحماية من الحريق ولا عن تقييم المخاطر. البيانات دون ضمان.",

