dp_1h: "1. الجهة المسؤولة",
dp_2h: "2. أهم النقاط باختصار",
dp_2p: "مخطط المستودعات أداة حسابية بحتة تعمل بالكامل داخل متصفحك. لا يتم <strong>نقل مدخلاتك (الأصناف والأبعاد والأوزان والكميات والإعدادات) إلينا أو إلى أطراف ثالثة ولا يتم حفظها</strong>. وتختفي بعد إعادة تحميل الصفحة. لا يوجد تسجيل ولا ملفات تعريف ارتباط (Cookies) ولا تتبع ولا أدوات تحليل ولا إعلانات.",
dp_3h: "3. الاستضافة وملفات سجل الخادم",
dp_3p: "يتم استضافة هذا الموقع لدى Cloudflare, Inc., 101 Townsend St., San Francisco, CA 94107, USA (Cloudflare Pages). عند الزيارة تعالج Cloudflare بيانات الاتصال الضرورية تقنيًا، ولا سيما عنوان IP والتاريخ والوقت والملف المطلوب ونوع المتصفح ونظام التشغيل. وهذا ضروري لتقديم الصفحة وحمايتها من الهجمات. الأساس القانوني هو المادة 6 (1)(و) من اللائحة العامة لحماية البيانات GDPR (DSGVO) (المصلحة المشروعة في تشغيل آمن وفعّال). قد تتم المعالجة في الولايات المتحدة؛ Cloudflare حاصلة على شهادة EU-US Data Privacy Framework، وتسري بالإضافة إلى ذلك البنود التعاقدية القياسية. لمزيد من المعلومات: <a href=\"https://www.cloudflare.com/privacypolicy/\" target=\"_blank\" rel=\"noopener\">cloudflare.com/privacypolicy</a>.",
dp_4h: "4. لا محتوى من مزودين خارجيين",
dp_4p: "يتم تحميل الخطوط (Barlow, Barlow Condensed, JetBrains Mono, Vazirmatn) ومكتبة العرض ثلاثي الأبعاد three.js مباشرة من خادم الويب هذا. لا يوجد أي اتصال بـ Google Fonts أو شبكات توصيل المحتوى (CDN) أو أي خوادم أخرى لأطراف ثالثة.",
dp_5h: "5. التخزين في متصفحك",
dp_5p: "لا نستخدم ملفات تعريف الارتباط. يتم حفظ اللغة التي اخترتها فقط في Local Storage الخاص بمتصفحك، حتى تبقى محفوظة في زيارتك التالية. هذا التخزين ضروري تمامًا للوظيفة التي طلبتها (§ 25 Abs. 2 Nr. 2 TDDDG). يمكنك حذفه في أي وقت من خلال إعدادات متصفحك.",
dp_6h: "6. التواصل عبر البريد الإلكتروني أو الهاتف",
dp_6p: "عندما تتواصل معنا، نعالج بياناتك (مثل الاسم وعنوان البريد الإلكتروني ومحتوى الرسالة) حصريًا لمعالجة طلبك. الأساس القانوني هو المادة 6 (1)(ب) من اللائحة العامة لحماية البيانات GDPR (DSGVO) (طلب سابق للتعاقد) أو المادة 6 (1)(و) من اللائحة العامة لحماية البيانات GDPR (DSGVO) (المصلحة المشروعة في الرد). نحذف البيانات بمجرد الانتهاء من معالجة الطلب نهائيًا وعدم وجود التزامات قانونية بالاحتفاظ.",
dp_7h: "7. حقوقك",
dp_7p: "لديك الحق في الاطلاع (المادة 15 من GDPR)، والتصحيح (المادة 16)، والحذف (المادة 17)، وتقييد المعالجة (المادة 18)، ونقل البيانات (المادة 20). وبقدر ما تستند المعالجة إلى المادة 6 (1)(و) من اللائحة العامة لحماية البيانات GDPR (DSGVO)، يمكنك الاعتراض عليها في أي وقت (المادة 21 من GDPR). تكفي رسالة غير رسمية إلى عنوان البريد الإلكتروني المذكور أعلاه. ويمكنك أيضًا تقديم شكوى إلى سلطة رقابية لحماية البيانات، على سبيل المثال المفوض الحكومي لحماية البيانات وحرية المعلومات في ولاية بادن-فورتمبيرغ (Landesbeauftragter für den Datenschutz und die Informationsfreiheit Baden-Württemberg)، Lautenschlagerstraße 20, 70173 Stuttgart، <a href=\"https://www.baden-wuerttemberg.datenschutz.de\" target=\"_blank\" rel=\"noopener\">baden-wuerttemberg.datenschutz.de</a>.",
dp_8h: "8. التغييرات",
dp_8p: "نقوم بتعديل سياسة الخصوصية هذه عند تغير وظائف الموقع. وتسري النسخة المنشورة هنا في حينه.",
im_h: "بيانات الناشر (Impressum)",
im_sub: "البيانات وفقًا لـ § 5 DDG",
im_provider: "مقدم الخدمة",
im_brand: "يعمل تحت العلامة التجارية KeyOne",
