im_resp_p: "Rahmatallah Fakhri Fakhrabadi، العنوان كما هو مذكور أعلاه",
im_liab: "إخلاء المسؤولية",
im_liab_p: "يقدم مخطط المستودعات قيمًا استرشادية غير ملزمة للتخطيط الأولي. جميع النتائج دون ضمان ولا تغني عن التخطيط المتخصص ولا عن الحسابات الإنشائية ولا عن مفهوم الحماية من الحريق ولا عن تقييم المخاطر. يتحمل مشغلو الروابط الخارجية وحدهم المسؤولية عن محتواها.",
im_dispute: "تسوية نزاعات المستهلكين",
im_dispute_p: "لسنا مستعدين ولا ملزمين بالمشاركة في إجراءات تسوية النزاعات أمام هيئة تحكيم المستهلكين.",
im_copy: "حقوق النشر",
im_copy_p: "تخضع النصوص والتصميم والشيفرة البرمجية لهذه الأداة لقانون حقوق النشر الألماني. ويتطلب أي استغلال خارج حدود قانون حقوق النشر موافقة كتابية من مقدم الخدمة. الخطوط المستخدمة مرخصة بموجب SIL Open Font License، وthree.js بموجب ترخيص MIT.",
close: "إغلاق"
