h_assume: "Varsayımlar ve mevzuat",
as_1: "Yük birimi: Ürünler seçilen yük taşıyıcıya katlar halinde istiflenir (yatay düzlemde döndürmeye izin verilir), yük yüksekliği ve maksimum ağırlıkla sınırlıdır.",
as_2: "Küçük parçalar (≤ 600 mm, ≤ 15 kg, ≤ 30 l, düşük miktar) raf sistemine gider (göz 950 × 480 × 380 mm, 6 kat, göz başına maks. 100 kg). 2,5 m'den uzun malzemeler konsol rafa gider.",
as_3: "Palet rafı: 3 Euro palet (travers 2,7 m) veya 2 endüstriyel palet için bölme, kat başına 250 mm boşluk, tavan/sprinklerin altında 1 m mesafe. Koridor genişlikleri (referans): karşı ağırlıklı forklift 3,8 m, reach truck 2,9 m, dar koridor 1,8 m, istif vinci 1,6 m, konsol raf 2,4 m, raf sistemi 1,2 m.",
as_4: "Normal ürün için otomatik teknoloji seçimi: 2.500 palet yerinden itibaren yüksek raflı depo (izin verilmişse), 1.200 yerden ve ≥ 9 m holden itibaren dar koridor, aksi halde reach truck. Dondurulmuş/soğuk ürünlerde 150 yerden itibaren hareketli raf (koridor alanı ve soğutma enerjisi tasarrufu).",
as_5: "Tehlikeli maddeler, depolama sınıfına göre ayrı bir binada kendi depo bölümünde (temkinli varsayım). Birlikte depolama durum bazında TRGS 510 Ek 4'e göre kontrol edilmelidir.",
as_6: "Performans (saat başına çevrim): karşı ağırlıklı forklift 20, reach truck 18, dar koridor 22, istif vinci 35, çok yönlü forklift 12, yatay taşıma 25, toplama 80 satır/saat, vardiya başına 6,5 verimli saat. TIR başına 33 palet, kapı başına saatte 1 TIR, pik faktörü 1,5.",
as_7: "Mevzuat (Almanya): DIN EN 15512 / 15620 / 15635 (raflar), DGUV Regel 108-007 (depo donanımları), DGUV Vorschrift 68 (iç lojistik araçları), ASR A1.8 (trafik yolları), ASR A2.2 (yangın koruma), ASR A2.3 (kaçış yolları), ASR A3.4 (aydınlatma), ASR A4.1/A4.2 (sıhhi tesisler/dinlenme odaları), TRGS 510 (tehlikeli madde depolama), AwSV (toplama hacimleri), MIndBauRL (endüstriyel yapılar).",
disclaimer: "Ön planlama için referans değerlerdir. Uzman planlamanın, yangın koruma konseptinin ve risk değerlendirmesinin yerini tutmaz. Bilgiler garanti verilmeksizin sunulmuştur.",

// ---------- Yasal ----------
foot_privacy: "Gizlilik",
foot_imprint: "Künye",
legal_note: "Bu çeviri yalnızca bilgilendirme amaçlıdır; hukuken bağlayıcı olan Almanca sürümdür.",
dp_h: "Gizlilik Politikası",
dp_stand: "Güncelleme: Ekim 2026",
dp_1h: "1. Sorumlu",
dp_2h: "2. Özetle en önemli bilgiler",
dp_2p: "Depo planlayıcı, tamamen tarayıcınızda çalışan saf bir hesaplama aracıdır. Girdileriniz (ürünler, ölçüler, ağırlıklar, miktarlar ve ayarlar) <strong>bize veya üçüncü taraflara aktarılmaz ve kaydedilmez</strong>. Sayfa yeniden yüklendiğinde silinirler. Kayıt, çerez, izleme, analiz aracı veya reklam yoktur.",
dp_3h: "3. Barındırma ve sunucu günlük dosyaları",
dp_3p: "Bu web sitesi Cloudflare, Inc., 101 Townsend St., San Francisco, CA 94107, ABD (Cloudflare Pages) tarafından barındırılmaktadır. Sayfa açıldığında Cloudflare teknik olarak gerekli bağlantı verilerini, özellikle IP adresi, tarih ve saat, istenen dosya, tarayıcı türü ve işletim sistemini işler. Bu, sayfanın sunulması ve saldırılara karşı korunması için gereklidir. Hukuki dayanak GDPR (DSGVO) md. 6/1-f'dir (güvenli ve işlevsel bir işletmeye ilişkin meşru menfaat). ABD'de işleme mümkündür; Cloudflare EU-US Data Privacy Framework kapsamında sertifikalıdır, ek olarak standart sözleşme maddeleri geçerlidir. Daha fazla bilgi: <a href=\"https://www.cloudflare.com/privacypolicy/\" target=\"_blank\" rel=\"noopener\">cloudflare.com/privacypolicy</a>.",
dp_4h: "4. Üçüncü taraf içeriği yok",
dp_4p: "Yazı tipleri (Barlow, Barlow Condensed, JetBrains Mono, Vazirmatn) ve 3D kütüphanesi three.js doğrudan bu web sunucusundan yüklenir. Google Fonts, içerik dağıtım ağları veya diğer üçüncü taraf sunucularla bağlantı kurulmaz.",
dp_5h: "5. Tarayıcınızda depolama",
dp_5p: "Çerez kullanmıyoruz. Tarayıcınızın Local Storage alanında yalnızca seçtiğiniz dil, bir sonraki ziyaretinizde korunması için kaydedilir. Bu depolama, talep ettiğiniz işlev için kesinlikle gereklidir (§ 25 Abs. 2 Nr. 2 TDDDG). Bunu istediğiniz zaman tarayıcı ayarlarınızdan silebilirsiniz.",
dp_6h: "6. E-posta veya telefonla iletişim",
dp_6p: "Bizimle iletişime geçtiğinizde bilgilerinizi (ör. ad, e-posta adresi, mesaj içeriği) yalnızca talebinizi işlemek için işleriz. Hukuki dayanak GDPR (DSGVO) md. 6/1-b (sözleşme öncesi talep) veya md. 6/1-f'dir (yanıtlamaya ilişkin meşru menfaat). Talep nihai olarak işlendikten ve yasal saklama yükümlülükleri sona erdikten sonra verileri sileriz.",
dp_7h: "7. Haklarınız",
dp_7p: "Bilgi edinme (GDPR (DSGVO) md. 15), düzeltme (md. 16), silme (md. 17), işlemenin kısıtlanması (md. 18) ve veri taşınabilirliği (md. 20) haklarına sahipsiniz. İşleme GDPR (DSGVO) md. 6/1-f'ye dayandığı ölçüde, istediğiniz zaman itiraz edebilirsiniz (GDPR (DSGVO) md. 21). Yukarıda belirtilen e-posta adresine şekil şartı olmayan bir mesaj yeterlidir. Ayrıca bir veri koruma denetim makamına, örneğin Baden-Württemberg Veri Koruma ve Bilgi Edinme Özgürlüğü Komiserliği'ne, Lautenschlagerstraße 20, 70173 Stuttgart, <a href=\"https://www.baden-wuerttemberg.datenschutz.de\" target=\"_blank\" rel=\"noopener\">baden-wuerttemberg.datenschutz.de</a> şikâyette bulunabilirsiniz.",
dp_8h: "8. Değişiklikler",
dp_8p: "Web sitesinin işlevleri değiştiğinde bu gizlilik politikasını güncelleriz. Burada yayımlanan güncel sürüm geçerlidir.",
im_h: "Künye",
