im_liab: "Sorumluluk notu",
im_liab_p: "Depo planlayıcı, ön planlama için bağlayıcı olmayan referans değerler sunar. Tüm sonuçlar garanti verilmeksizin sunulur ve uzman planlamanın, statik hesabın, yangın koruma konseptinin ve risk değerlendirmesinin yerini tutmaz. Harici bağlantıların içeriğinden yalnızca bunların işletmecileri sorumludur.",
