h_assume: "Ipotesi e normative",
as_1: "Unità di carico: gli articoli vengono disposti a strati sul supporto di carico scelto (rotazione nel piano consentita), nei limiti di altezza di carico e peso massimo.",
as_2: "La minuteria (≤ 600 mm, ≤ 15 kg, ≤ 30 l, quantità ridotte) va nella scaffalatura a ripiani (vano 950 × 480 × 380 mm, 6 livelli, max. 100 kg/vano). La merce lunga oltre 2,5 m va nella scaffalatura cantilever.",
as_3: "Scaffalatura portapallet: campata per 3 europallet (correnti 2,7 m) o 2 pallet industriali, franco 250 mm per livello, 1 m di distanza da soffitto/sprinkler. Larghezze corsia (valori indicativi): carrello frontale 3,8 m, retrattile 2,9 m, corsia stretta 1,8 m, TE 1,6 m, cantilever 2,4 m, ripiani 1,2 m.",
as_4: "Scelta automatica della tecnologia per merce normale: da 2.500 posti pallet magazzino automatico (se consentito), da 1.200 posti e capannone ≥ 9 m corsia stretta, altrimenti retrattile. Surgelato/refrigerato da 150 posti scaffalatura compattabile (risparmia superficie di corsia ed energia frigorifera).",
as_5: "Merci pericolose per classe di stoccaggio in una sezione dedicata di un edificio separato (ipotesi prudenziale). Verificare caso per caso lo stoccaggio congiunto secondo TRGS 510 Allegato 4.",
as_6: "Prestazioni (cicli all'ora): carrello frontale 20, retrattile 18, corsia stretta 22, TE 35, carrello multidirezionale 12, trasporto orizzontale 25, picking 80 righe/h, 6,5 ore produttive per turno. 33 pallet per camion, 1 camion per baia e ora, fattore di picco 1,5.",
as_7: "Normative (Germania): DIN EN 15512 / 15620 / 15635 (scaffalature), DGUV Regel 108-007 (attrezzature di magazzino), DGUV Vorschrift 68 (carrelli industriali), ASR A1.8 (vie di circolazione), ASR A2.2 (antincendio), ASR A2.3 (vie di fuga), ASR A3.4 (illuminazione), ASR A4.1/A4.2 (servizi igienici/sale pausa), TRGS 510 (stoccaggio sostanze pericolose), AwSV (bacini di contenimento), MIndBauRL (edilizia industriale).",
