// ---------- Note legali ----------
foot_privacy: "Privacy",
foot_imprint: "Impressum",
legal_note: "Questa traduzione è fornita a solo scopo informativo; fa fede la versione tedesca.",
dp_h: "Informativa sulla privacy",
dp_stand: "Aggiornata a: ottobre 2026",
dp_1h: "1. Titolare del trattamento",
dp_2h: "2. In sintesi",
dp_2p: "Il Lagerplaner è un puro strumento di calcolo che funziona interamente nel tuo browser. I dati inseriti (articoli, dimensioni, pesi, quantità e impostazioni) <strong>non vengono trasmessi a noi né a terzi e non vengono salvati</strong>. Dopo aver ricaricato la pagina scompaiono. Non ci sono registrazione, cookie, tracciamento, strumenti di analisi né pubblicità.",
dp_3h: "3. Hosting e file di log del server",
dp_3p: "Questo sito è ospitato da Cloudflare, Inc., 101 Townsend St., San Francisco, CA 94107, USA (Cloudflare Pages). All'accesso, Cloudflare tratta i dati di connessione tecnicamente necessari, in particolare indirizzo IP, data e ora, file richiesto, tipo di browser e sistema operativo. Ciò è necessario per fornire la pagina e proteggerla da attacchi. La base giuridica è l'art. 6, par. 1, lett. f GDPR (legittimo interesse a un funzionamento sicuro ed efficiente). È possibile un trattamento negli USA; Cloudflare è certificata nell'ambito dell'EU-US Data Privacy Framework e si applicano inoltre le clausole contrattuali standard. Ulteriori informazioni: <a href=\"https://www.cloudflare.com/privacypolicy/\" target=\"_blank\" rel=\"noopener\">cloudflare.com/privacypolicy</a>.",
dp_4h: "4. Nessun contenuto di terze parti",
dp_4p: "I font (Barlow, Barlow Condensed, JetBrains Mono, Vazirmatn) e la libreria 3D three.js vengono caricati direttamente da questo server web. Non vi è alcuna connessione a Google Fonts, reti di distribuzione di contenuti (CDN) o altri server di terzi.",
dp_5h: "5. Memorizzazione nel tuo browser",
dp_5p: "Non utilizziamo cookie. Nel Local Storage del tuo browser viene salvata esclusivamente la lingua da te scelta, affinché venga mantenuta alla visita successiva. Questa memorizzazione è strettamente necessaria per la funzione da te richiesta (§ 25 Abs. 2 Nr. 2 TDDDG). Puoi cancellarla in qualsiasi momento tramite le impostazioni del browser.",
dp_6h: "6. Contatto via e-mail o telefono",
dp_6p: "Se ci contatti, trattiamo i tuoi dati (ad es. nome, indirizzo e-mail, contenuto del messaggio) esclusivamente per gestire la tua richiesta. La base giuridica è l'art. 6, par. 1, lett. b GDPR (richiesta precontrattuale) o lett. f GDPR (legittimo interesse a rispondere). Cancelliamo i dati non appena la richiesta è stata definitivamente evasa e non sussistono obblighi legali di conservazione.",
dp_7h: "7. I tuoi diritti",
dp_7p: "Hai diritto di accesso (art. 15 GDPR), rettifica (art. 16), cancellazione (art. 17), limitazione del trattamento (art. 18) e portabilità dei dati (art. 20). Se un trattamento si basa sull'art. 6, par. 1, lett. f GDPR, puoi opporti in qualsiasi momento (art. 21 GDPR). È sufficiente un messaggio informale all'indirizzo e-mail indicato sopra. Puoi inoltre presentare reclamo a un'autorità di controllo per la protezione dei dati, ad esempio al Landesbeauftragter für den Datenschutz und die Informationsfreiheit Baden-Württemberg, Lautenschlagerstraße 20, 70173 Stoccarda, <a href=\"https://www.baden-wuerttemberg.datenschutz.de\" target=\"_blank\" rel=\"noopener\">baden-wuerttemberg.datenschutz.de</a>.",
dp_8h: "8. Modifiche",
dp_8p: "Aggiorniamo questa informativa sulla privacy non appena cambiano le funzioni del sito. Vale la versione di volta in volta pubblicata qui.",
im_h: "Impressum",
im_sub: "Informazioni ai sensi del § 5 DDG",
im_provider: "Fornitore",
im_brand: "Operante con il marchio KeyOne",
im_country: "Germania",
im_contact: "Contatti",
