im_email: "E-mail",
im_resp: "Responsabile dei contenuti ai sensi del § 18 Abs. 2 MStV",
im_resp_p: "Rahmatallah Fakhri Fakhrabadi, indirizzo come sopra",
im_liab: "Esclusione di responsabilità",
im_liab_p: "Il Lagerplaner fornisce valori indicativi non vincolanti per la progettazione preliminare. Tutti i risultati sono senza garanzia e non sostituiscono la progettazione specialistica, i calcoli statici, il piano antincendio né la valutazione dei rischi. Dei contenuti dei link esterni sono responsabili esclusivamente i rispettivi gestori.",
im_dispute: "Risoluzione delle controversie con i consumatori",
im_dispute_p: "Non siamo disposti né obbligati a partecipare a procedure di risoluzione delle controversie dinanzi a un organismo di conciliazione per i consumatori.",
im_copy: "Diritto d'autore",
im_copy_p: "Testi, grafica e codice di questo strumento sono soggetti al diritto d'autore tedesco. Qualsiasi utilizzo al di fuori dei limiti del diritto d'autore richiede il consenso scritto del fornitore. I font utilizzati sono distribuiti con licenza SIL Open Font License, three.js con licenza MIT.",
close: "Chiudi"
