dp_h: "Politique de confidentialité",
dp_stand: "Mise à jour : octobre 2026",
dp_1h: "1. Responsable du traitement",
dp_2h: "2. L'essentiel en bref",
dp_2p: "Le planificateur d'entrepôt est un simple outil de calcul qui fonctionne entièrement dans votre navigateur. Vos saisies (articles, dimensions, poids, quantités et paramètres) ne sont <strong>ni transmises à nous ou à des tiers, ni enregistrées</strong>. Elles disparaissent au rechargement de la page. Il n'y a ni inscription, ni cookies, ni suivi, ni outils d'analyse, ni publicité.",
dp_3h: "3. Hébergement et journaux serveur",
dp_3p: "Ce site est hébergé par Cloudflare, Inc., 101 Townsend St., San Francisco, CA 94107, États-Unis (Cloudflare Pages). Lors de l'accès, Cloudflare traite les données de connexion techniquement nécessaires, notamment l'adresse IP, la date et l'heure, le fichier consulté, le type de navigateur et le système d'exploitation. Cela est nécessaire pour diffuser la page et la protéger contre les attaques. La base juridique est l'art. 6, par. 1, point f) du RGPD (DSGVO) (intérêt légitime à un fonctionnement sûr et opérationnel). Un traitement aux États-Unis est possible ; Cloudflare est certifié selon le EU-US Data Privacy Framework, des clauses contractuelles types s'appliquent en complément. Plus d'informations : <a href=\"https://www.cloudflare.com/privacypolicy/\" target=\"_blank\" rel=\"noopener\">cloudflare.com/privacypolicy</a>.",
dp_4h: "4. Aucun contenu de tiers",
dp_4p: "Les polices (Barlow, Barlow Condensed, JetBrains Mono, Vazirmatn) et la bibliothèque 3D three.js sont chargées directement depuis ce serveur web. Il n'y a aucune connexion à Google Fonts, à des réseaux de diffusion de contenu (CDN) ou à d'autres serveurs tiers.",
dp_5h: "5. Stockage dans votre navigateur",
dp_5p: "Nous n'utilisons pas de cookies. Seule la langue que vous avez choisie est enregistrée dans le Local Storage de votre navigateur afin d'être conservée lors de votre prochaine visite. Ce stockage est strictement nécessaire à la fonction que vous avez demandée (§ 25 Abs. 2 Nr. 2 TDDDG). Vous pouvez le supprimer à tout moment via les paramètres de votre navigateur.",
dp_6h: "6. Contact par e-mail ou téléphone",
dp_6p: "Si vous nous contactez, nous traitons vos données (p. ex. nom, adresse e-mail, contenu du message) uniquement pour traiter votre demande. La base juridique est l'art. 6, par. 1, point b) du RGPD (DSGVO) (demande précontractuelle) ou point f) du RGPD (intérêt légitime à répondre). Nous supprimons les données dès que la demande est entièrement traitée et qu'aucune obligation légale de conservation ne s'applique.",
dp_7h: "7. Vos droits",
dp_7p: "Vous disposez d'un droit d'accès (art. 15 RGPD (DSGVO)), de rectification (art. 16), d'effacement (art. 17), de limitation du traitement (art. 18) et à la portabilité des données (art. 20). Lorsqu'un traitement repose sur l'art. 6, par. 1, point f) du RGPD, vous pouvez vous y opposer à tout moment (art. 21 RGPD). Un simple message à l'adresse e-mail indiquée ci-dessus suffit. Vous pouvez également introduire une réclamation auprès d'une autorité de contrôle de la protection des données, par exemple le Landesbeauftragter für den Datenschutz und die Informationsfreiheit Baden-Württemberg (délégué régional à la protection des données et à la liberté d'information du Bade-Wurtemberg), Lautenschlagerstraße 20, 70173 Stuttgart, <a href=\"https://www.baden-wuerttemberg.datenschutz.de\" target=\"_blank\" rel=\"noopener\">baden-wuerttemberg.datenschutz.de</a>.",
dp_8h: "8. Modifications",
dp_8p: "Nous adaptons cette politique de confidentialité dès que les fonctions du site changent. La version publiée ici fait foi.",
im_h: "Mentions légales (Impressum)",
