im_resp_p: "Rahmatallah Fakhri Fakhrabadi, adresse ci-dessus",
im_liab: "Limitation de responsabilité",
im_liab_p: "Le planificateur d'entrepôt fournit des valeurs indicatives non contractuelles pour l'avant-projet. Tous les résultats sont sans garantie et ne remplacent ni une étude spécialisée, ni un calcul de structure, ni un concept de protection incendie, ni une évaluation des risques. Seuls les exploitants des liens externes sont responsables de leur contenu.",
