as_1: "하역 단위: 품목은 선택한 적재 용기 위에 층별로 적재되며(수평면 회전 허용), 적재 높이와 최대 중량으로 제한됩니다.",
as_2: "소형 부품(≤ 600 mm, ≤ 15 kg, ≤ 30 l, 소량)은 선반 랙에 보관합니다(칸 950 × 480 × 380 mm, 6단, 칸당 최대 100 kg). 2.5 m 초과 장척물은 캔틸레버 랙에 보관합니다.",
as_3: "팔레트 랙: 베이당 유로 팔레트 3개(빔 2.7 m) 또는 산업용 팔레트 2개, 단당 여유 250 mm, 천장/스프링클러 아래 1 m 이격. 통로 폭(기준값): 카운터밸런스 지게차 3.8 m, 리치 트럭 2.9 m, 협소통로 1.8 m, 스태커 크레인 1.6 m, 캔틸레버 2.4 m, 선반 랙 1.2 m.",
as_4: "일반 화물 설비 자동 선택: 팔레트 로케이션 2,500개 이상이면 자동화 고층 창고(허용 시), 1,200개 이상이고 창고 높이 ≥ 9 m이면 협소통로, 그 외에는 리치 트럭. 냉동/냉장은 150개 이상이면 이동식 랙(통로 면적과 냉각 에너지 절감).",
as_5: "위험물은 보관 등급별로 별도 건물 내 전용 보관 구역에 보관합니다(보수적 가정). 혼재 보관은 TRGS 510 부록 4에 따라 개별 검토하세요.",
as_6: "처리 능력(시간당 사이클): 카운터밸런스 지게차 20, 리치 트럭 18, 협소통로 22, 스태커 크레인 35, 다방향 지게차 12, 수평 운반 25, 피킹 80라인/h, 교대당 생산 시간 6.5시간. 트럭당 33팔레트, 도크당 시간당 트럭 1대, 피크 계수 1.5.",
as_7: "규정(독일): DIN EN 15512 / 15620 / 15635(랙), DGUV Regel 108-007(보관 설비), DGUV Vorschrift 68(운반 차량), ASR A1.8(통행로), ASR A2.2(방화), ASR A2.3(피난로), ASR A3.4(조명), ASR A4.1/A4.2(위생 시설/휴게실), TRGS 510(위험물 보관), AwSV(방유 공간), MIndBauRL(산업용 건축물).",
