dp_h: "개인정보 처리방침",
dp_stand: "최종 업데이트: 2026년 10월",
dp_1h: "1. 개인정보 처리 책임자",
dp_2h: "2. 핵심 요약",
dp_2p: "창고 플래너는 브라우저에서 완전히 실행되는 순수 계산 도구입니다. 입력하신 내용(품목, 치수, 중량, 수량 및 설정)은 <strong>당사나 제3자에게 전송되지 않으며 저장되지 않습니다</strong>. 페이지를 새로고침하면 사라집니다. 회원 가입, 쿠키, 추적, 분석 도구 및 광고가 없습니다.",
dp_3h: "3. 호스팅 및 서버 로그 파일",
dp_3p: "이 웹사이트는 Cloudflare, Inc., 101 Townsend St., San Francisco, CA 94107, USA(Cloudflare Pages)에서 호스팅됩니다. 접속 시 Cloudflare는 기술적으로 필요한 접속 데이터, 특히 IP 주소, 날짜 및 시간, 요청한 파일, 브라우저 유형 및 운영 체제를 처리합니다. 이는 페이지를 제공하고 공격으로부터 보호하기 위해 필요합니다. 법적 근거는 GDPR(DSGVO) 제6조 제1항 f호(안전하고 원활한 운영에 대한 정당한 이익)입니다. 미국에서 처리될 수 있으며, Cloudflare는 EU-US Data Privacy Framework 인증을 받았고 추가로 표준 계약 조항이 적용됩니다. 자세한 정보: <a href=\"https://www.cloudflare.com/privacypolicy/\" target=\"_blank\" rel=\"noopener\">cloudflare.com/privacypolicy</a>.",
dp_4h: "4. 제3자 콘텐츠 없음",
dp_4p: "글꼴(Barlow, Barlow Condensed, JetBrains Mono, Vazirmatn)과 3D 라이브러리 three.js는 이 웹 서버에서 직접 로드됩니다. Google Fonts, 콘텐츠 전송 네트워크(CDN) 또는 기타 제3자 서버와의 연결은 없습니다.",
dp_5h: "5. 브라우저 내 저장",
dp_5p: "당사는 쿠키를 사용하지 않습니다. 다음 방문 시에도 유지되도록 사용자가 선택한 언어만 브라우저의 Local Storage에 저장됩니다. 이 저장은 사용자가 요청한 기능에 반드시 필요합니다(§ 25 Abs. 2 Nr. 2 TDDDG). 브라우저 설정에서 언제든지 삭제할 수 있습니다.",
dp_6h: "6. 이메일 또는 전화 문의",
dp_6p: "문의하시는 경우, 당사는 귀하의 정보(예: 이름, 이메일 주소, 메시지 내용)를 문의 처리 목적으로만 처리합니다. 법적 근거는 GDPR(DSGVO) 제6조 제1항 b호(계약 전 문의) 또는 f호(답변에 대한 정당한 이익)입니다. 문의 처리가 완료되고 법정 보관 의무가 없으면 데이터를 삭제합니다.",
dp_7h: "7. 귀하의 권리",
dp_7p: "귀하는 열람권(GDPR(DSGVO) 제15조), 정정권(제16조), 삭제권(제17조), 처리 제한권(제18조) 및 데이터 이동권(제20조)을 가집니다. 처리가 GDPR 제6조 제1항 f호에 근거하는 경우 언제든지 이의를 제기할 수 있습니다(GDPR 제21조). 위에 기재된 이메일 주소로 형식 없이 연락하시면 됩니다. 또한 개인정보 감독 기관에 민원을 제기할 수 있습니다. 예: 바덴뷔르템베르크주 개인정보 보호 및 정보 자유 감독관(Landesbeauftragter für den Datenschutz und die Informationsfreiheit Baden-Württemberg), Lautenschlagerstraße 20, 70173 Stuttgart, <a href=\"https://www.baden-wuerttemberg.datenschutz.de\" target=\"_blank\" rel=\"noopener\">baden-wuerttemberg.datenschutz.de</a>.",
dp_8h: "8. 변경",
dp_8p: "웹사이트 기능이 변경되면 본 개인정보 처리방침을 수정합니다. 항상 여기에 게시된 최신판이 적용됩니다.",
