// ---------- 前提 ----------
h_assume: "前提 & 規格・法令",
as_1: "荷役単位：品目は選択した荷役用具に段積みされ(水平面での回転可)、積載高さと最大重量で制限されます。",
as_2: "小物部品(≤ 600 mm、≤ 15 kg、≤ 30 l、少量)は中量棚に保管します(棚 950 × 480 × 380 mm、6段、棚あたり最大100 kg)。2.5 mを超える長尺物はカンチレバーラックに保管します。",
as_3: "パレットラック：間口あたりユーロパレット3枚(ビーム2.7 m)または工業用パレット2枚、段ごとのクリアランス250 mm、天井/スプリンクラー下1 mの離隔。通路幅(目安値)：カウンターバランスフォークリフト3.8 m、リーチフォークリフト2.9 m、狭通路1.8 m、スタッカークレーン1.6 m、カンチレバー2.4 m、中量棚1.2 m。",
as_4: "一般品の設備自動選択：パレットロケーション2,500以上で自動立体倉庫(許可時)、1,200以上かつ天井高≥ 9 mで狭通路、それ以外はリーチフォークリフト。冷凍/冷蔵は150ロケーション以上で移動ラック(通路面積と冷却エネルギーを削減)。",
as_5: "危険物は保管クラスごとに別棟内の専用保管区画に保管します(安全側の仮定)。混合保管はTRGS 510付録4に基づき個別に確認してください。",
as_6: "処理能力(1時間あたりサイクル)：カウンターバランスフォークリフト20、リーチフォークリフト18、狭通路22、スタッカークレーン35、多方向フォークリフト12、水平搬送25、ピッキング80行/h、シフトあたり実働6.5時間。トラック1台あたり33パレット、ドックごとに1時間あたりトラック1台、ピーク係数1.5。",
as_7: "規格・法令(ドイツ)：DIN EN 15512 / 15620 / 15635(ラック)、DGUV Regel 108-007(保管設備)、DGUV Vorschrift 68(構内運搬車両)、ASR A1.8(通路)、ASR A2.2(防火)、ASR A2.3(避難経路)、ASR A3.4(照明)、ASR A4.1/A4.2(衛生設備/休憩室)、TRGS 510(危険物保管)、AwSV(防液堤)、MIndBauRL(工業建築物)。",
disclaimer: "基本計画用の目安値です。専門設計、防火計画、リスクアセスメントに代わるものではありません。内容の正確性は保証しません。",

