dp_3p: "本ウェブサイトは Cloudflare, Inc., 101 Townsend St., San Francisco, CA 94107, USA(Cloudflare Pages)でホスティングされています。アクセス時、Cloudflareは技術的に必要な接続データ、特にIPアドレス、日時、要求されたファイル、ブラウザの種類、OSを処理します。これはページの配信と攻撃からの保護のために必要です。法的根拠はGDPR(DSGVO)第6条1項(f)(安全かつ正常な運営に対する正当な利益)です。米国で処理される場合があります。CloudflareはEU-US Data Privacy Frameworkの認証を受けており、追加で標準契約条項が適用されます。詳細：<a href=\"https://www.cloudflare.com/privacypolicy/\" target=\"_blank\" rel=\"noopener\">cloudflare.com/privacypolicy</a>。",
