dp_4p: "フォント(Barlow、Barlow Condensed、JetBrains Mono、Vazirmatn)と3Dライブラリthree.jsは、本ウェブサーバーから直接読み込まれます。Google Fonts、コンテンツ配信ネットワーク(CDN)、その他の第三者サーバーへの接続はありません。",
dp_5h: "5. ブラウザ内での保存",
dp_5p: "当方はCookieを使用しません。次回訪問時にも保持されるよう、選択された言語のみがブラウザのLocal Storageに保存されます。この保存は、ご要望の機能に必要不可欠なものです(§ 25 Abs. 2 Nr. 2 TDDDG)。ブラウザの設定からいつでも削除できます。",
dp_6h: "6. メールまたは電話でのお問い合わせ",
dp_6p: "お問い合わせいただいた場合、当方はお客様の情報(例：氏名、メールアドレス、メッセージ内容)をお問い合わせへの対応のためにのみ処理します。法的根拠はGDPR(DSGVO)第6条1項(b)(契約前の問い合わせ)または(f)(回答に対する正当な利益)です。お問い合わせへの対応が完了し、法定の保存義務がない場合、データを削除します。",
dp_7h: "7. お客様の権利",
dp_7p: "お客様には、アクセス権(GDPR(DSGVO)第15条)、訂正権(第16条)、消去権(第17条)、処理制限権(第18条)、データポータビリティ権(第20条)があります。処理がGDPR第6条1項(f)に基づく場合、いつでも異議を申し立てることができます(GDPR第21条)。上記のメールアドレスへの形式自由のご連絡で足ります。また、データ保護監督機関に苦情を申し立てることもできます。例：バーデン＝ヴュルテンベルク州データ保護・情報自由監察官(Landesbeauftragter für den Datenschutz und die Informationsfreiheit Baden-Württemberg)、Lautenschlagerstraße 20, 70173 Stuttgart、<a href=\"https://www.baden-wuerttemberg.datenschutz.de\" target=\"_blank\" rel=\"noopener\">baden-wuerttemberg.datenschutz.de</a>。",
dp_8h: "8. 変更",
dp_8p: "ウェブサイトの機能が変更された場合、本プライバシーポリシーを改訂します。常にここに掲載されている最新版が適用されます。",
