// ---------- Supozimet ----------
h_assume: "Supozimet & rregulloret",
as_1: "Njësia e ngarkesës: artikujt vendosen në shtresa mbi mbajtësen e zgjedhur të ngarkesës (lejohet rrotullimi në plan horizontal), të kufizuar nga lartësia e ngarkesës dhe pesha maksimale.",
as_2: "Pjesët e vogla (≤ 600 mm, ≤ 15 kg, ≤ 30 l, sasi e vogël) shkojnë në rafte me rafta (ndarje 950 × 480 × 380 mm, 6 nivele, maks. 100 kg/ndarje). Mallrat e gjata mbi 2,5 m shkojnë në rafte konsol.",
as_3: "Rafte paletash: ndarje fushe për 3 europaleta (traversë 2,7 m) ose 2 paleta industriale, hapësirë e lirë 250 mm për nivel, 1 m largësi nën tavan/sprinklerë. Gjerësia e korridoreve (vlera orientuese): pirun frontal 3,8 m, reach truck 2,9 m, korridor i ngushtë 1,8 m, vinç magazinimi 1,6 m, konsol 2,4 m, rafte me rafta 1,2 m.",
as_4: "Zgjedhja automatike e teknologjisë për mall normal: nga 2.500 vende paletash magazinë e automatizuar me rafte të larta (nëse lejohet), nga 1.200 vende dhe sallë ≥ 9 m korridor i ngushtë, përndryshe reach truck. Të ngrira/të ftohura nga 150 vende rafte të lëvizshme (kursen sipërfaqe korridoresh dhe energji ftohjeje).",
as_5: "Mallrat e rrezikshme sipas klasës së magazinimit në seksion të veçantë të një ndërtese të veçantë (supozim i kujdesshëm). Magazinimi i përbashkët kontrollohet rast pas rasti sipas TRGS 510 Shtojca 4.",
as_6: "Performanca (cikle në orë): pirun frontal 20, reach truck 18, korridor i ngushtë 22, vinç magazinimi 35, pirun shumëdrejtimësh 12, transport horizontal 25, picking 80 poz./orë, 6,5 orë produktive për turn. 33 paleta për kamion, 1 kamion për derë dhe orë, faktor pik 1,5.",
as_7: "Rregulloret (Gjermani): DIN EN 15512 / 15620 / 15635 (rafte), DGUV Regel 108-007 (pajisje magazinimi), DGUV Vorschrift 68 (mjete transporti), ASR A1.8 (rrugë qarkullimi), ASR A2.2 (mbrojtja nga zjarri), ASR A2.3 (rrugë evakuimi), ASR A3.4 (ndriçimi), ASR A4.1/A4.2 (sanitare/dhoma pushimi), TRGS 510 (magazinimi i substancave të rrezikshme), AwSV (hapësira grumbullimi), MIndBauRL (ndërtesa industriale).",
disclaimer: "Vlera orientuese për planifikimin paraprak. Nuk zëvendëson planifikimin profesional, konceptin e mbrojtjes nga zjarri apo vlerësimin e rrezikut. Pa garanci.",

// ---------- Informacione ligjore ----------
foot_privacy: "Privatësia",
foot_imprint: "Impressum",
legal_note: "Ky përkthim ofrohet vetëm për informim; versioni gjerman është ligjërisht i detyrueshëm.",
dp_h: "Politika e privatësisë",
dp_stand: "Përditësuar: tetor 2026",
dp_1h: "1. Kontrolluesi",
dp_2h: "2. Më të rëndësishmet shkurtimisht",
dp_2p: "Planifikuesi i magazinës është një mjet i pastër llogaritjeje që funksionon tërësisht në shfletuesin tuaj. Të dhënat që futni (artikuj, përmasa, pesha, sasi dhe cilësime) <strong>nuk transmetohen te ne ose te palë të treta dhe nuk ruhen</strong>. Pas ringarkimit të faqes ato zhduken. Nuk ka regjistrim, cookies, gjurmim, mjete analize apo reklama.",
dp_3h: "3. Hostimi dhe skedarët log të serverit",
dp_3p: "Kjo faqe interneti hostohet nga Cloudflare, Inc., 101 Townsend St., San Francisco, CA 94107, USA (Cloudflare Pages). Gjatë aksesit, Cloudflare përpunon të dhëna lidhjeje teknikisht të nevojshme, veçanërisht adresën IP, datën dhe orën, skedarin e kërkuar, llojin e shfletuesit dhe sistemin operativ. Kjo është e nevojshme për të shfaqur faqen dhe për ta mbrojtur nga sulmet. Baza ligjore është neni 6, paragrafi 1, shkronja f e GDPR (DSGVO) (interes legjitim për një funksionim të sigurt dhe të rregullt). Përpunimi në SHBA është i mundur; Cloudflare është i certifikuar sipas EU-US Data Privacy Framework, dhe shtesë zbatohen klauzolat standarde kontraktuale. Më shumë informacion: <a href=\"https://www.cloudflare.com/privacypolicy/\" target=\"_blank\" rel=\"noopener\">cloudflare.com/privacypolicy</a>.",
dp_4h: "4. Pa përmbajtje nga palë të treta",
dp_4p: "Shkronjat (Barlow, Barlow Condensed, JetBrains Mono, Vazirmatn) dhe biblioteka 3D three.js ngarkohen drejtpërdrejt nga ky server. Nuk ka lidhje me Google Fonts, rrjete shpërndarjeje përmbajtjeje (CDN) ose servera të tjerë të palëve të treta.",
dp_5h: "5. Ruajtja në shfletuesin tuaj",
dp_5p: "Ne nuk përdorim cookies. Në Local Storage të shfletuesit tuaj ruhet vetëm gjuha që keni zgjedhur, që të mbetet në vizitën e ardhshme. Kjo ruajtje është rreptësisht e nevojshme për funksionin që keni kërkuar (§ 25 Abs. 2 Nr. 2 TDDDG). Mund ta fshini në çdo kohë përmes cilësimeve të shfletuesit.",
dp_6h: "6. Kontakti me email ose telefon",
dp_6p: "Nëse na kontaktoni, ne përpunojmë të dhënat tuaja (p.sh. emrin, adresën e email-it, përmbajtjen e mesazhit) vetëm për trajtimin e kërkesës suaj. Baza ligjore është neni 6, paragrafi 1, shkronja b e GDPR (DSGVO) (kërkesë parakontraktuale) ose neni 6, paragrafi 1, shkronja f e GDPR (interes legjitim për përgjigjen). Ne i fshijmë të dhënat sapo kërkesa të jetë trajtuar përfundimisht dhe nuk ka detyrime ligjore ruajtjeje.",
dp_7h: "7. Të drejtat tuaja",
dp_7p: "Ju keni të drejtën e informimit (neni 15 i GDPR (DSGVO)), korrigjimit (neni 16), fshirjes (neni 17), kufizimit të përpunimit (neni 18) dhe transferueshmërisë së të dhënave (neni 20). Kur përpunimi bazohet në nenin 6, paragrafi 1, shkronja f e GDPR, mund të kundërshtoni në çdo kohë (neni 21 i GDPR). Mjafton një mesazh i thjeshtë në adresën e email-it të përmendur më lart. Gjithashtu mund të paraqisni ankesë pranë një autoriteti mbikëqyrës për mbrojtjen e të dhënave, për shembull te Komisioneri Shtetëror për Mbrojtjen e të Dhënave dhe Lirinë e Informacionit Baden-Württemberg (Landesbeauftragter für den Datenschutz und die Informationsfreiheit Baden-Württemberg), Lautenschlagerstraße 20, 70173 Stuttgart, <a href=\"https://www.baden-wuerttemberg.datenschutz.de\" target=\"_blank\" rel=\"noopener\">baden-wuerttemberg.datenschutz.de</a>.",
dp_8h: "8. Ndryshimet",
dp_8p: "Ne e përshtatim këtë politikë privatësie sapo ndryshojnë funksionet e faqes. Vlen versioni i publikuar këtu në çdo kohë.",
im_h: "Impressum (Njoftim ligjor)",
im_sub: "Informacion sipas § 5 DDG",
im_provider: "Ofruesi",
im_brand: "Vepron nën markën KeyOne",
im_country: "Gjermani",
im_contact: "Kontakti",
im_phone: "Telefoni",
im_email: "Email",
im_resp: "Përgjegjës për përmbajtjen sipas § 18 Abs. 2 MStV",
im_resp_p: "Rahmatallah Fakhri Fakhrabadi, adresa si më lart",
im_liab: "Shënim për përgjegjësinë",
im_liab_p: "Planifikuesi i magazinës jep vlera orientuese jo detyruese për planifikimin paraprak. Të gjitha rezultatet jepen pa garanci dhe nuk zëvendësojnë planifikimin profesional, llogaritjet statike, konceptin e mbrojtjes nga zjarri apo vlerësimin e rrezikut. Për përmbajtjen e lidhjeve të jashtme përgjegjës janë vetëm operatorët e tyre.",
im_dispute: "Zgjidhja e mosmarrëveshjeve me konsumatorët",
im_dispute_p: "Ne nuk jemi të gatshëm dhe nuk jemi të detyruar të marrim pjesë në procedura të zgjidhjes së mosmarrëveshjeve para një organi pajtimi për konsumatorët.",
im_copy: "E drejta e autorit",
im_copy_p: "Tekstet, dizajni dhe kodi i programit të këtij mjeti i nënshtrohen ligjit gjerman për të drejtën e autorit. Çdo përdorim jashtë kufijve të së drejtës së autorit kërkon pëlqimin me shkrim të ofruesit. Shkronjat e përdorura janë nën SIL Open Font License, three.js nën licencën MIT.",
close: "Mbyll"
