dp_2p: "برنامه‌ریز انبار یک ابزار محاسباتی صرف است که به‌طور کامل در مرورگر شما اجرا می‌شود. ورودی‌های شما (کالاها، ابعاد، وزن‌ها، مقادیر و تنظیمات) <strong>به ما یا اشخاص ثالث ارسال نمی‌شوند و ذخیره نمی‌شوند</strong>. پس از بارگذاری مجدد صفحه، این داده‌ها از بین می‌روند. هیچ ثبت‌نام، کوکی، ردیابی توسط اشخاص ثالث یا تبلیغاتی وجود ندارد. تنها یک آمار بازدید ناشناس و تجمیعی ثبت می‌شود (نگاه کنید به بند 3).",
