as2_3: "Gjerësia e korridoreve (vlera orientuese): pirun frontal 3,8 m, reach truck 2,9 m, korridor i ngushtë 1,8 m, vinç magazinimi 1,6 m, konsol 2,4 m, rafte me rafta 1,2 m. 1 m largësi nën tavan/sprinklerë.",
as2_4: "Zgjedhja e teknologjisë për mall normal: nga 2.500 vende paletash magazinë me rafte të larta (nëse lejohet), nga 1.200 vende dhe sallë ≥ 9 m korridor i ngushtë, përndryshe reach truck. Të ftohura/të ngrira nga 150 vende rafte të lëvizshme.",
