privacy_badge: "Të gjitha llogaritjet kryhen vetëm në shfletuesin tuaj – të dhënat tuaja nuk transmetohen dhe nuk ruhen.",
dp_2p: "Planifikuesi i magazinës është një mjet i pastër llogaritjeje që funksionon tërësisht në shfletuesin tuaj. Të dhënat që futni (artikuj, përmasa, pesha, sasi dhe cilësime) <strong>nuk transmetohen te ne ose te palë të treta dhe nuk ruhen</strong>. Pas ringarkimit të faqes ato zhduken. Nuk ka regjistrim, cookies, gjurmim nga palë të treta apo reklama. Mbahet vetëm një statistikë anonime dhe e përmbledhur e vizitave (shih pikën 3).",
dp_3h: "3. Hostimi, skedarët log të serverit dhe statistika anonime e vizitave",
dp_3p2: "<strong>Statistika anonime e vizitave:</strong> Për të kuptuar se cilat faqe dhe funksione zgjojnë interes, ne numërojmë në formë të përmbledhur shfaqjet e faqeve dhe klikimet mbi butonat dhe lidhjet. Për këtë, gjatë hapjes së faqes ose klikimit të një elementi, një skript i vogël dërgon një njoftim te serveri i vetë kësaj faqeje interneti (<code>/api/track</code>), i cili përpunohet në infrastrukturën e Cloudflare në një bazë të dhënash Cloudflare D1. Ruhen vetëm numërues ditorë me të dhënat e mëposhtme: data (pa orën), shtegu i hapur ose emërtimi i elementit të klikuar, gjuha e zgjedhur, domeni i faqes referuese (pa adresën e plotë) dhe vendi i nxjerrë nga lidhja. Të dhënat që futni në planifikuesin e magazinës, adresat IP, identifikuesit e shfletuesit, të dhënat e pajisjes apo identifikues të tjerë nuk ruhen; nuk vendosen cookies dhe nuk krijohen profile përdoruesish. Nuk është e mundur të nxirren përfundime për vizitorë individualë; botët e njohur nuk numërohen. Baza ligjore është neni 6, paragrafi 1, shkronja f e GDPR (DSGVO) (interes legjitim për ta përmirësuar shërbimin në bazë të përdorimit). Mund të kundërshtoni në çdo kohë duke na kontaktuar përmes të dhënave të kontaktit të përmendura më lart ose duke çaktivizuar JavaScript në shfletuesin tuaj."
